"%' OR pd.full_description LIKE '%href="https://superi.ge/category-45/"%');
CREATE TABLE IF NOT EXISTS superi_bk_page_41 AS SELECT d.page_id, d.lang_code, d.description FROM cscart_page_descriptions d WHERE d.description LIKE '%superi.ge/notebook-ka/%' OR (d.description LIKE '%<h1%' AND (d.description LIKE '%OLED vs QLED vs mini-LED%' OR d.description LIKE '%<title>%'));
SET @et := (SELECT s.type FROM cscart_seo_names s JOIN cscart_product_feature_variant_descriptions vd ON vd.variant_id = s.object_id AND vd.lang_code = 'ka' WHERE s.name = 'samsung' AND s.lang_code = 'ka' AND vd.variant = 'SAMSUNG' LIMIT 1);
SET @bf := (SELECT v.feature_id FROM cscart_product_feature_variants v JOIN cscart_seo_names s ON s.object_id = v.variant_id AND s.type = @et AND s.lang_code = 'ka' WHERE s.name = 'samsung' LIMIT 1);
CREATE TABLE IF NOT EXISTS superi_bk_fv_41 AS SELECT v.variant_id, v.url FROM cscart_product_feature_variants v JOIN cscart_seo_names s ON s.object_id = v.variant_id AND s.type = @et AND s.lang_code = 'ka' WHERE s.name IN ('bosch', 'canyon', 'crown', 'dewalt-instrumentebi', 'honor', 'marazzi', 'ugreen') AND v.url <> '';

-- 1-2) მეტა აღწერები და ბაღის ავეჯის სახელები
DROP TEMPORARY TABLE IF EXISTS tmp_m41;
CREATE TEMPORARY TABLE tmp_m41 AS SELECT s.name AS slug, pd.product AS new_name, pd.meta_description AS new_meta FROM cscart_seo_names s JOIN cscart_product_descriptions pd ON pd.product_id = s.object_id LIMIT 0;
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 JOIN tmp_m41 t ON t.slug = s.name SET pd.page_title = CASE WHEN REPLACE(pd.page_title, ' ', '') = REPLACE(pd.product, ' ', '') THEN t.new_name WHEN REPLACE(pd.page_title, ' ', '') = CONCAT(REPLACE(pd.product, ' ', ''), '|Superi.ge') THEN CONCAT(t.new_name, ' | Superi.ge') ELSE pd.page_title END WHERE pd.lang_code = 'ka' AND t.new_name <> '' AND IFNULL(pd.page_title, '') <> '';
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 JOIN tmp_m41 t ON t.slug = s.name SET pd.product = t.new_name WHERE pd.lang_code = 'ka' AND t.new_name <> '';
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 JOIN tmp_m41 t ON t.slug = s.name SET pd.meta_description = t.new_meta WHERE pd.lang_code = 'ka';

-- 3) ბრენდის დამატება (იგივე ჩანაწერი, რაც იმავე ბრენდის სხვა პროდუქტს აქვს)
DROP TEMPORARY TABLE IF EXISTS tmp_b41;
CREATE TEMPORARY TABLE tmp_b41 AS SELECT name AS pslug, name AS rslug FROM cscart_seo_names LIMIT 0;
CREATE TABLE IF NOT EXISTS superi_bk_brand_41 AS SELECT ps.object_id AS product_id FROM tmp_b41 t JOIN cscart_seo_names ps ON ps.name = t.pslug AND ps.type = 'p' AND ps.lang_code = 'ka' AND ps.company_id = 1 WHERE NOT EXISTS (SELECT 1 FROM cscart_product_features_values x WHERE x.product_id = ps.object_id AND x.feature_id = @bf AND x.variant_id > 0);

-- 4) ბრენდის გვერდები: „URL“ ველში საკუთარი მისამართი ეწერა
UPDATE cscart_product_feature_variants v JOIN cscart_seo_names s ON s.object_id = v.variant_id AND s.type = @et AND s.lang_code = 'ka' SET v.url = '' WHERE s.name IN ('bosch', 'canyon', 'crown', 'dewalt-instrumentebi', 'honor', 'marazzi', 'ugreen') AND (v.url LIKE '%superi.ge%' OR v.url NOT LIKE 'http%');

-- 5) ბმულები აღწერებში — პირდაპირ სწორ მისამართზე
UPDATE cscart_product_descriptions pd SET pd.full_description = REPLACE(pd.full_description, 'href="https://SUPERI.GE/BOSCH"', 'href="https://superi.ge/bosch/"') WHERE pd.lang_code = 'ka' AND pd.full_description LIKE '%href="https://SUPERI.GE/BOSCH"%';
UPDATE cscart_product_descriptions pd SET pd.full_description = REPLACE(pd.full_description, 'href="https://superi.ge/intex"', 'href="https://superi.ge/intex/"') WHERE pd.lang_code = 'ka' AND pd.full_description LIKE '%href="https://superi.ge/intex"%';
UPDATE cscart_product_descriptions pd SET pd.full_description = REPLACE(pd.full_description, 'href="https://superi.ge/category-45/"', 'href="https://superi.ge/aveji/"') WHERE pd.lang_code = 'ka' AND pd.full_description LIKE '%href="https://superi.ge/category-45/"%';
UPDATE cscart_page_descriptions d SET d.description = REPLACE(d.description, 'https://superi.ge/notebook-ka/', 'https://superi.ge/noutbuqebi/') WHERE d.description LIKE '%superi.ge/notebook-ka/%';

-- 6) მეორე H1 → H2; ზედმეტი <title> ტექსტში
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 SET pd.full_description = REPLACE(REPLACE(pd.full_description, '<h1', '<h2'), '</h1>', '</h2>') WHERE pd.lang_code = 'ka' AND s.name = 'samsung-ww11cb944cghlp-11kg' AND pd.full_description LIKE '%<h1%';
UPDATE cscart_page_descriptions d SET d.description = REPLACE(REPLACE(d.description, '<h1', '<h2'), '</h1>', '</h2>') WHERE d.description LIKE '%<h1%' AND (d.description LIKE '%OLED vs QLED vs mini-LED%' OR d.description LIKE '%<title>%');
UPDATE cscart_page_descriptions d SET d.description = REGEXP_REPLACE(d.description, '<title>[^<]*</title>', '') WHERE d.description LIKE '%<title>%';

-- 7) სურათების alt: პროდუქტის სახელი (მთავარი ფოტო) / „სახელი – ფოტო N“ (დამატებითი); მხოლოდ ცარიელს ავსებს
DROP TEMPORARY TABLE IF EXISTS tmp_alt41;
CREATE TEMPORARY TABLE tmp_alt41 AS SELECT cd.object_id AS img_id, cd.description AS alt FROM cscart_common_descriptions cd LIMIT 0;
ALTER TABLE tmp_alt41 ADD PRIMARY KEY (img_id);
DELETE t FROM tmp_alt41 t JOIN cscart_common_descriptions cd ON cd.object_id = t.img_id AND cd.object_holder = 'images' AND cd.lang_code = 'ka' WHERE TRIM(IFNULL(cd.description, '')) <> '';
CREATE TABLE IF NOT EXISTS superi_bk_alt_41 AS SELECT t.img_id, (SELECT COUNT(*) FROM cscart_common_descriptions x WHERE x.object_id = t.img_id AND x.object_holder = 'images' AND x.lang_code = 'ka') AS had_row FROM tmp_alt41 t;
UPDATE cscart_common_descriptions cd JOIN tmp_alt41 t ON t.img_id = cd.object_id SET cd.description = t.alt WHERE cd.object_holder = 'images' AND cd.lang_code = 'ka' AND TRIM(IFNULL(cd.description, '')) = '';

-- 8) შემოწმება
SELECT COUNT(*) AS products, SUM(pd.meta_description LIKE '%ნაწილ-ნაწილ%' OR CHAR_LENGTH(pd.meta_description) >= 60) AS good_metas, SUM(pd.meta_description LIKE '•%' OR pd.meta_description LIKE '·%' OR pd.meta_description LIKE '%გაეცანით მახასიათებლებს%') AS old_metas_left FROM cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 JOIN tmp_m41 t ON t.slug = s.name WHERE pd.lang_code = 'ka';
SELECT pd.product, pd.page_title FROM cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 JOIN tmp_m41 t ON t.slug = s.name AND t.new_name <> '' WHERE pd.lang_code = 'ka' ORDER BY pd.product;
SELECT COUNT(DISTINCT b.product_id) AS products_need_brand, COUNT(DISTINCT fv.product_id) AS brand_added FROM superi_bk_brand_41 b LEFT JOIN cscart_product_features_values fv ON fv.product_id = b.product_id AND fv.variant_id > 0 AND fv.feature_id = @bf;
SELECT s.name AS brand, v.url FROM cscart_product_feature_variants v JOIN cscart_seo_names s ON s.object_id = v.variant_id AND s.type = @et AND s.lang_code = 'ka' WHERE s.name IN ('bosch', 'canyon', 'crown', 'dewalt-instrumentebi', 'honor', 'marazzi', 'ugreen');
SELECT (SELECT COUNT(*) FROM cscart_product_descriptions WHERE lang_code = 'ka' AND (full_description LIKE '%href="https://SUPERI.GE/BOSCH"%' OR full_description LIKE '%href="https://superi.ge/intex"%' OR full_description LIKE '%href="https://superi.ge/category-45/"%')) AS old_links_left, (SELECT COUNT(*) FROM cscart_page_descriptions WHERE description LIKE '%notebook-ka%' OR description LIKE '%<title>%') AS page_issues_left, (SELECT COUNT(*) FROM tmp_alt41) AS alts_filled;
DROP TEMPORARY TABLE IF EXISTS tmp_m41;
DROP TEMPORARY TABLE IF EXISTS tmp_b41;
DROP TEMPORARY TABLE IF EXISTS tmp_alt41;

