INSERT IGNORE INTO cscart_product_features_values (feature_id, product_id, variant_id, value, value_int, lang_code) SELECT fv.feature_id, ps.object_id, fv.variant_id, fv.value, fv.value_int, fv.lang_code FROM tmp_b41 t JOIN cscart_seo_names ps ON ps.name = t.pslug AND ps.type = 'p' AND ps.lang_code = 'ka' AND ps.company_id = 1 JOIN cscart_seo_names rs ON rs.name = t.rslug AND rs.type = 'p' AND rs.lang_code = 'ka' AND rs.company_id = 1 JOIN cscart_product_features_values fv ON fv.product_id = rs.object_id AND fv.feature_id = @bf AND fv.variant_id > 0 WHERE NOT EXISTS (SELECT 1 FROM cscart_product_features_values x WHERE x.product_id = ps.object_id AND x.feature_id = @bf AND x.variant_id > 0);
INSERT IGNORE INTO tmp_alt41 (img_id, alt) SELECT x.img_id, IF(x.type = 'M', x.product, CONCAT(x.product, ' – ფოტო ', x.n + 1)) FROM (SELECT il.detailed_id AS img_id, il.type, pd.product, ROW_NUMBER() OVER (PARTITION BY il.object_id, il.type ORDER BY il.position, il.pair_id) AS n FROM cscart_images_links il JOIN cscart_product_descriptions pd ON pd.product_id = il.object_id AND pd.lang_code = 'ka' WHERE il.object_type = 'product' AND il.detailed_id > 0 AND TRIM(pd.product) <> '') x;
INSERT IGNORE INTO tmp_alt41 (img_id, alt) SELECT x.img_id, IF(x.type = 'M', x.product, CONCAT(x.product, ' – ფოტო ', x.n + 1)) FROM (SELECT il.image_id AS img_id, il.type, pd.product, ROW_NUMBER() OVER (PARTITION BY il.object_id, il.type ORDER BY il.position, il.pair_id) AS n FROM cscart_images_links il JOIN cscart_product_descriptions pd ON pd.product_id = il.object_id AND pd.lang_code = 'ka' WHERE il.object_type = 'product' AND il.image_id > 0 AND TRIM(pd.product) <> '') x;
INSERT IGNORE INTO tmp_alt41 (img_id, alt) SELECT il.detailed_id, MAX(vd.variant) FROM cscart_images_links il JOIN cscart_product_feature_variant_descriptions vd ON vd.variant_id = il.object_id AND vd.lang_code = 'ka' WHERE il.object_type = 'feature_variant' AND il.detailed_id > 0 AND TRIM(vd.variant) <> '' GROUP BY il.detailed_id;
INSERT IGNORE INTO tmp_alt41 (img_id, alt) SELECT il.image_id, MAX(vd.variant) FROM cscart_images_links il JOIN cscart_product_feature_variant_descriptions vd ON vd.variant_id = il.object_id AND vd.lang_code = 'ka' WHERE il.object_type = 'feature_variant' AND il.image_id > 0 AND TRIM(vd.variant) <> '' GROUP BY il.image_id;
INSERT INTO cscart_common_descriptions (object_id, description, lang_code, object_holder) SELECT t.img_id, t.alt, 'ka', 'images' FROM tmp_alt41 t WHERE NOT EXISTS (SELECT 1 FROM cscart_common_descriptions x WHERE x.object_id = t.img_id AND x.object_holder = 'images' AND x.lang_code = 'ka');
